import Rgb from '../../../src/utils/Rgb.js';

describe('Rgb', () => {
  describe('reset', () => {
    it('should reset all color components to 255', () => {
      const rgb = new Rgb(100, 150, 200);

      rgb.reset();

      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);
    });

    it('should reset colors when initialized with default values', () => {
      const rgb = new Rgb();

      rgb.reset();

      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);
    });

    it('should reset colors when initialized with negative values', () => {
      const rgb = new Rgb(-10, -20, -30);

      rgb.reset();

      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);
    });

    it('should reset colors when initialized with values above 255', () => {
      const rgb = new Rgb(300, 400, 500);

      rgb.reset();

      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);
    });

    it('should reset colors multiple times correctly', () => {
      const rgb = new Rgb(0, 0, 0);

      rgb.reset();
      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);

      rgb.r = 50;
      rgb.g = 100;
      rgb.b = 150;

      rgb.reset();
      expect(rgb.r).toBe(255);
      expect(rgb.g).toBe(255);
      expect(rgb.b).toBe(255);
    });

    it('should maintain independent instances after reset', () => {
      const rgb1 = new Rgb(100, 150, 200);
      const rgb2 = new Rgb(10, 20, 30);

      rgb1.reset();

      expect(rgb1.r).toBe(255);
      expect(rgb1.g).toBe(255);
      expect(rgb1.b).toBe(255);

      expect(rgb2.r).toBe(10);
      expect(rgb2.g).toBe(20);
      expect(rgb2.b).toBe(30);
    });
  });
});

