import Particle from '../../../src/core/Particle.js';

describe('Particle', () => {
  describe('destroy', () => {
    let particle;

    beforeEach(() => {
      particle = new Particle();
    });

    it('should set energy to 0', () => {
      particle.energy = 100;
      particle.destroy();
      expect(particle.energy).toBe(0);
    });

    it('should set dead to true', () => {
      particle.dead = false;
      particle.destroy();
      expect(particle.dead).toBe(true);
    });

    it('should set parent to null', () => {
      particle.parent = { some: 'object' };
      particle.destroy();
      expect(particle.parent).toBeNull();
    });

    it('should call removeAllBehaviours', () => {
      const mockRemoveAllBehaviours = jest.fn();
      particle.removeAllBehaviours = mockRemoveAllBehaviours;

      particle.destroy();

      expect(mockRemoveAllBehaviours).toHaveBeenCalledTimes(1);
    });

    it('should maintain other properties unchanged', () => {
      const originalId = particle.id;
      const originalP = particle.p;
      const originalV = particle.v;
      const originalA = particle.a;
      const originalRgb = particle.rgb;
      const originalOld = particle.old;
      const originalData = particle.data;
      const originalBehaviours = particle.behaviours;

      particle.destroy();

      expect(particle.id).toBe(originalId);
      expect(particle.p).toBe(originalP);
      expect(particle.v).toBe(originalV);
      expect(particle.a).toBe(originalA);
      expect(particle.rgb).toBe(originalRgb);
      expect(particle.old).toBe(originalOld);
      expect(particle.data).toBe(originalData);
      expect(particle.behaviours).toBe(originalBehaviours);
    });

    it('should work correctly when called multiple times', () => {
      particle.energy = 50;
      particle.dead = false;
      particle.parent = { obj: 'parent' };

      particle.destroy();
      expect(particle.energy).toBe(0);
      expect(particle.dead).toBe(true);
      expect(particle.parent).toBeNull();

      particle.destroy();
      expect(particle.energy).toBe(0);
      expect(particle.dead).toBe(true);
      expect(particle.parent).toBeNull();
    });

    it('should work with initial null/undefined values', () => {
      const newParticle = new Particle();
      newParticle.energy = undefined;
      newParticle.dead = undefined;
      newParticle.parent = undefined;

      newParticle.destroy();

      expect(newParticle.energy).toBe(0);
      expect(newParticle.dead).toBe(true);
      expect(newParticle.parent).toBeNull();
    });
  });
});

