import Particle from '../../../src/core/Particle.js';

describe('Particle', () => {
  describe('removeBehaviour', () => {
    let particle;
    let mockBehaviour1;
    let mockBehaviour2;
    let mockBehaviour3;

    beforeEach(() => {
      particle = new Particle();
      mockBehaviour1 = { name: 'Behaviour1' };
      mockBehaviour2 = { name: 'Behaviour2' };
      mockBehaviour3 = { name: 'Behaviour3' };

      particle.behaviours = [mockBehaviour1, mockBehaviour2, mockBehaviour3];
    });

    it('should remove the specified behaviour from behaviours array when it exists', () => {
      particle.removeBehaviour(mockBehaviour2);

      expect(particle.behaviours).toHaveLength(2);
      expect(particle.behaviours).toContain(mockBehaviour1);
      expect(particle.behaviours).toContain(mockBehaviour3);
      expect(particle.behaviours).not.toContain(mockBehaviour2);
    });

    it('should set parents to null for the removed behaviour', () => {
      // Create a fresh behaviour object to avoid reference issues
      const behaviourToRemove = { name: 'TestBehaviour', parents: [particle] };
      particle.behaviours = [behaviourToRemove, mockBehaviour2, mockBehaviour3];

      particle.removeBehaviour(behaviourToRemove);

      expect(behaviourToRemove.parents).toBeNull();
    });

    it('should not modify behaviours array when behaviour is not found', () => {
      const nonExistentBehaviour = { name: 'NonExistent' };
      const originalBehaviours = [...particle.behaviours];

      particle.removeBehaviour(nonExistentBehaviour);

      expect(particle.behaviours).toEqual(originalBehaviours);
    });

    it('should handle removing behaviour from empty behaviours array', () => {
      particle.behaviours = [];

      particle.removeBehaviour(mockBehaviour1);

      expect(particle.behaviours).toHaveLength(0);
    });

    it('should handle removing the first behaviour in the array', () => {
      const behaviourToRemove = { name: 'FirstBehaviour', parents: [particle] };
      particle.behaviours = [behaviourToRemove, mockBehaviour2, mockBehaviour3];

      particle.removeBehaviour(behaviourToRemove);

      expect(particle.behaviours).toHaveLength(2);
      expect(particle.behaviours[0]).toBe(mockBehaviour2);
      expect(particle.behaviours[1]).toBe(mockBehaviour3);
      expect(behaviourToRemove.parents).toBeNull();
    });

    it('should handle removing the last behaviour in the array', () => {
      const behaviourToRemove = { name: 'LastBehaviour', parents: [particle] };
      particle.behaviours = [mockBehaviour1, mockBehaviour2, behaviourToRemove];

      particle.removeBehaviour(behaviourToRemove);

      expect(particle.behaviours).toHaveLength(2);
      expect(particle.behaviours[0]).toBe(mockBehaviour1);
      expect(particle.behaviours[1]).toBe(mockBehaviour2);
      expect(particle.behaviours).not.toContain(behaviourToRemove);
      expect(behaviourToRemove.parents).toBeNull();
    });

    it('should handle removing a behaviour that appears multiple times (removes only first occurrence)', () => {
      const duplicateBehaviour = { name: 'Duplicate', parents: [particle] };
      particle.behaviours = [mockBehaviour1, duplicateBehaviour, mockBehaviour2, duplicateBehaviour];

      particle.removeBehaviour(duplicateBehaviour);

      expect(particle.behaviours).toHaveLength(3);
      expect(particle.behaviours[0]).toBe(mockBehaviour1);
      expect(particle.behaviours[1]).toBe(mockBehaviour2);
      expect(particle.behaviours[2]).toBe(duplicateBehaviour);
      expect(duplicateBehaviour.parents).toBeNull();
    });

    it('should handle undefined behaviours array gracefully', () => {
      particle.behaviours = undefined;

      expect(() => {
        particle.removeBehaviour(mockBehaviour1);
      }).not.toThrow();

      // After the call, behaviours should still be undefined
      expect(particle.behaviours).toBeUndefined();
    });

    it('should handle null behaviours array gracefully', () => {
      particle.behaviours = null;

      expect(() => {
        particle.removeBehaviour(mockBehaviour1);
      }).not.toThrow();

      // After the call, behaviours should still be null
      expect(particle.behaviours).toBeNull();
    });

    it('should not throw error when removing null behaviour', () => {
      expect(() => {
        particle.removeBehaviour(null);
      }).not.toThrow();
    });

    it('should not throw error when removing undefined behaviour', () => {
      expect(() => {
        particle.removeBehaviour(undefined);
      }).not.toThrow();
    });
  });
});

