  });

  test('should return true for point inside rectangle', () => {
    expect(rectangle.contains(15, 30)).toBe(true);
    expect(rectangle.contains(10, 20)).toBe(true); // top-left corner
    expect(rectangle.contains(40, 60)).toBe(true); // bottom-right corner
    expect(rectangle.contains(25, 40)).toBe(true); // center point
  });

  test('should return true for point on rectangle edges', () => {
    expect(rectangle.contains(10, 30)).toBe(true); // left edge
    expect(rectangle.contains(40, 20)).toBe(true); // top edge
    expect(rectangle.contains(40, 60)).toBe(true); // right edge
    expect(rectangle.contains(15, 60)).toBe(true); // bottom edge
  });

  test('should return false for point outside rectangle', () => {
    expect(rectangle.contains(5, 30)).toBe(false); // left of rectangle
    expect(rectangle.contains(45, 30)).toBe(false); // right of rectangle
    expect(rectangle.contains(15, 15)).toBe(false); // above rectangle
    expect(rectangle.contains(15, 65)).toBe(false); // below rectangle
    expect(rectangle.contains(5, 15)).toBe(false); // top-left outside
    expect(rectangle.contains(45, 65)).toBe(false); // bottom-right outside
  });

  test('should handle negative coordinates', () => {
    const negativeRect = new Rectangle(-10, -20, 30, 40);
    expect(negativeRect.contains(-5, -10)).toBe(true);
    expect(negativeRect.contains(-10, -20)).toBe(true); // corner
    expect(negativeRect.contains(20, 20)).toBe(true); // opposite corner
    expect(negativeRect.contains(-15, -10)).toBe(false); // left outside
    expect(negativeRect.contains(-5, -25)).toBe(false); // above outside
  });

  test('should handle zero dimensions', () => {
