    expect(zeroRect.contains(10, 20)).toBe(true); // exactly at the point
    expect(zeroRect.contains(10.1, 20)).toBe(false);
    expect(zeroRect.contains(10, 20.1)).toBe(false);
    expect(zeroRect.contains(9.9, 20)).toBe(false);
  });

  test('should handle floating point coordinates', () => {
    expect(rectangle.contains(10.5, 30.5)).toBe(true);
    expect(rectangle.contains(9.999, 30)).toBe(false);
    expect(rectangle.contains(40.001, 30)).toBe(false);
  });

  test('should work with rectangle at origin', () => {
    const originRect = new Rectangle(0, 0, 50, 50);
    expect(originRect.contains(0, 0)).toBe(true);
    expect(originRect.contains(25, 25)).toBe(true);
    expect(originRect.contains(50, 50)).toBe(true);
    expect(originRect.contains(-1, 25)).toBe(false);
    expect(originRect.contains(25, -1)).toBe(false);
  });

