        lineZone.getDirection = jest.fn(() => false);

        lineZone.crossing(mockParticle);

        expect(mockParticle.dead).toBe(false);
      });

      it('should kill particle when rangeOut returns true and getDirection returns false', () => {
        lineZone.rangeOut = jest.fn(() => true);
        lineZone.getDirection = jest.fn(() => false);

        lineZone.crossing(mockParticle);

        expect(mockParticle.dead).toBe(true);
      });

      it('should not kill particle when rangeOut returns true and getDirection returns true', () => {
        lineZone.rangeOut = jest.fn(() => true);
        lineZone.getDirection = jest.fn(() => true);

        lineZone.crossing(mockParticle);

        expect(mockParticle.dead).toBe(false);
      });
    });
  });

  describe('crossType = "bound"', () => {
    beforeEach(() => {
      lineZone = new LineZone(0, 0, 10, 10);
      lineZone.crossType = 'bound';
    });

