      lineZone.rangeOut = jest.fn(() => true);
      lineZone.getDistance = jest.fn(() => 10);
      const originalV = { ...mockParticle.v };

      lineZone.crossing(mockParticle);

      expect(mockParticle.v).toEqual(originalV);
    });

    describe('when distance <= particle radius', () => {
      beforeEach(() => {
        lineZone.rangeOut = jest.fn(() => true);
        lineZone.getDistance = jest.fn(() => 4);
