      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should return correct squared distance for negative coordinates', () => {
      const v1 = new Vector2D(-1, -2);
      const v2 = new Vector2D(-4, -6);
      const dx = -1 - (-4);
      const dy = -2 - (-6);
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should return correct squared distance for mixed positive/negative coordinates', () => {
      const v1 = new Vector2D(-1, 2);
      const v2 = new Vector2D(3, -4);
      const dx = -1 - 3;
      const dy = 2 - (-4);
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should return correct squared distance when one vector is at origin', () => {
      const v1 = new Vector2D(0, 0);
      const v2 = new Vector2D(3, 4);
      const expected = 3 * 3 + 4 * 4;
      expect(v1.distanceToSquared(v2)).toBe(expected);
      expect(v2.distanceToSquared(v1)).toBe(expected);
    });

    test('should return correct squared distance for decimal coordinates', () => {
      const v1 = new Vector2D(1.5, 2.5);
      const v2 = new Vector2D(3.5, 4.5);
      const dx = 1.5 - 3.5;
      const dy = 2.5 - 4.5;
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should handle large coordinate values', () => {
      const v1 = new Vector2D(1000000, 2000000);
      const v2 = new Vector2D(3000000, 4000000);
      const dx = 1000000 - 3000000;
      const dy = 2000000 - 4000000;
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should be commutative (distance from v1 to v2 equals distance from v2 to v1)', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = new Vector2D(4, 6);
      expect(v1.distanceToSquared(v2)).toBe(v2.distanceToSquared(v1));
    });

    test('should work with vectors created with default constructor (0,0)', () => {
      const v1 = new Vector2D();
      const v2 = new Vector2D(3, 4);
      const expected = 3 * 3 + 4 * 4;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should handle invalid input gracefully', () => {
      const v1 = new Vector2D(1, 2);

      // Test with null - should throw TypeError
      expect(() => v1.distanceToSquared(null)).toThrow(TypeError);

      // Test with undefined - should throw TypeError
      expect(() => v1.distanceToSquared(undefined)).toThrow(TypeError);

      // Test with empty object - should return NaN (undefined - undefined = NaN)
      const resultEmptyObj = v1.distanceToSquared({});
      expect(isNaN(resultEmptyObj)).toBe(true);

      // Test with object missing y property
      const resultMissingY = v1.distanceToSquared({ x: 1 });
      expect(isNaN(resultMissingY)).toBe(true);

      // Test with object missing x property
      const resultMissingX = v1.distanceToSquared({ y: 2 });
      expect(isNaN(resultMissingX)).toBe(true);
    });

    test('should work with objects that have x and y properties', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = {
        x: 4,
        y: 6
      };
      const dx = 1 - 4;
      const dy = 2 - 6;
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should work with Vector2D instances', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = new Vector2D(4, 6);
      const dx = 1 - 4;
      const dy = 2 - 6;
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should handle objects with non-numeric x and y properties', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = {
        x: '4',
        y: '6'
      };
      // String subtraction results in NaN in JavaScript
      const result = v1.distanceToSquared(v2);
      expect(isNaN(result)).toBe(true);
    });

    test('should handle objects with x and y as zero', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = {
        x: 0,
        y: 0
      };
      const expected = 1 * 1 + 2 * 2;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });

    test('should handle objects with x and y as negative values', () => {
      const v1 = new Vector2D(1, 2);
      const v2 = {
        x: -3,
        y: -4
      };
      const dx = 1 - (-3);
      const dy = 2 - (-4);
      const expected = dx * dx + dy * dy;
      expect(v1.distanceToSquared(v2)).toBe(expected);
    });
  });
});

