    };

    // Setup Mat3.create mock to return the array passed to it
    MockMat3.create.mockImplementation((arr) => arr);

    // Create a fresh instance for each test
    renderer = new WebGLRenderer(mockElement);
  });

  afterEach(() => {
    // Clean up global mocks
    delete global.MStack;
    delete global.Mat3;
  });

  describe('initVar', () => {
