describe('BehaviourEmitter.update', () => {
  let behaviourEmitter;
  let mockSelfBehaviour1;
  let mockSelfBehaviour2;

  beforeEach(() => {
    behaviourEmitter = new BehaviourEmitter({});
    mockSelfBehaviour1 = {
      applyBehaviour: jest.fn()
    };
    mockSelfBehaviour2 = {
      applyBehaviour: jest.fn()
    };
  });

  it('should call super.update with the provided time', () => {
    const mockTime = 1000;
    const superUpdateSpy = jest.spyOn(Object.getPrototypeOf(Object.getPrototypeOf(behaviourEmitter)), 'update');

    behaviourEmitter.update(mockTime);

    expect(superUpdateSpy).toHaveBeenCalledWith(mockTime);
  });

  it('should apply all selfBehaviours when not sleeping', () => {
    behaviourEmitter.selfBehaviours = [mockSelfBehaviour1, mockSelfBehaviour2];
    const mockTime = 500;

    behaviourEmitter.update(mockTime);

    expect(mockSelfBehaviour1.applyBehaviour).toHaveBeenCalledWith(behaviourEmitter, mockTime, 0);
    expect(mockSelfBehaviour2.applyBehaviour).toHaveBeenCalledWith(behaviourEmitter, mockTime, 1);
  });

  it('should not apply any selfBehaviours when sleeping', () => {
    behaviourEmitter.selfBehaviours = [mockSelfBehaviour1, mockSelfBehaviour2];
    behaviourEmitter.sleep = true;
    const mockTime = 750;

    behaviourEmitter.update(mockTime);

    expect(mockSelfBehaviour1.applyBehaviour).not.toHaveBeenCalled();
    expect(mockSelfBehaviour2.applyBehaviour).not.toHaveBeenCalled();
  });

  it('should handle empty selfBehaviours array', () => {
    behaviourEmitter.selfBehaviours = [];
    const mockTime = 300;

    expect(() => {
      behaviourEmitter.update(mockTime);
    }).not.toThrow();
  });

  it('should pass correct index to each behaviour', () => {
    behaviourEmitter.selfBehaviours = [mockSelfBehaviour1, mockSelfBehaviour2];
    const mockTime = 200;

    behaviourEmitter.update(mockTime);

    expect(mockSelfBehaviour1.applyBehaviour).toHaveBeenCalledWith(expect.anything(), expect.anything(), 0);
    expect(mockSelfBehaviour2.applyBehaviour).toHaveBeenCalledWith(expect.anything(), expect.anything(), 1);
  });

  it('should work with single selfBehaviour', () => {
    behaviourEmitter.selfBehaviours = [mockSelfBehaviour1];
    const mockTime = 150;

    behaviourEmitter.update(mockTime);

    expect(mockSelfBehaviour1.applyBehaviour).toHaveBeenCalledWith(behaviourEmitter, mockTime, 0);
  });

  it('should handle different time values', () => {
    behaviourEmitter.selfBehaviours = [mockSelfBehaviour1];
    const timeValues = [0, 100, 1000, 9999];

