import Particle from '../../../src/core/Particle.js';
import Vector2D from '../../../src/math/Vector2D.js';

describe('Cyclone.applyBehaviour', () => {
  let cyclone;
  let particle;
  let mockTime;
  let mockIndex;

  beforeEach(() => {
    mockTime = 0.5;
    mockIndex = 0;
    particle = new Particle();
    particle.v = new Vector2D(10, 0);
    particle.a = new Vector2D(0, 0);
    particle.data = {
      cyclone: new Vector2D(0, 0),
      cangle: Math.PI / 4
    };
  });

  describe('with fixed angle and fixed force', () => {
    beforeEach(() => {
      cyclone = new Cyclone(Math.PI / 2, 5, 1);
    });

    it('should apply cyclone force with fixed angle and fixed force', () => {
      const originalGradient = particle.v.getGradient();
      const expectedGradient = originalGradient + Math.PI / 2;
      const expectedX = 5 * Math.cos(expectedGradient);
      const expectedY = 5 * Math.sin(expectedGradient);

      cyclone.applyBehaviour(particle, mockTime, mockIndex);

      expect(particle.data.cyclone.x).toBeCloseTo(expectedX);
      expect(particle.data.cyclone.y).toBeCloseTo(expectedY);
      expect(particle.a.x).toBeCloseTo(expectedX);
      expect(particle.a.y).toBeCloseTo(expectedY);
    });

    it('should normalize the cyclone force vector', () => {
      cyclone.applyBehaviour(particle, mockTime, mockIndex);

      const magnitude = Math.sqrt(
        particle.data.cyclone.x * particle.data.cyclone.x +
        particle.data.cyclone.y * particle.data.cyclone.y
      );
      expect(magnitude).toBeCloseTo(5);
    });
  });

  describe('with "random" angle and fixed force', () => {
    beforeEach(() => {
      cyclone = new Cyclone('random', 3, 1);
    });

    it('should use particle.data.cangle when angle is "random"', () => {
      const originalGradient = particle.v.getGradient();
      const expectedGradient = originalGradient + particle.data.cangle;
      const expectedX = 3 * Math.cos(expectedGradient);
      const expectedY = 3 * Math.sin(expectedGradient);

      cyclone.applyBehaviour(particle, mockTime, mockIndex);

      expect(particle.data.cyclone.x).toBeCloseTo(expectedX);
      expect(particle.data.cyclone.y).toBeCloseTo(expectedY);
    });
  });

  describe('with "span" angle and fixed force', () => {
    beforeEach(() => {
      cyclone = new Cyclone('span', 2, 1);
    });

    it('should use particle.data.cangle when angle is "span"', () => {
