import Pool from '../../../src/core/Pool.js';

describe('Pool', () => {
  describe('destroy', () => {
    let pool;

    beforeEach(() => {
      pool = new Pool();
    });

    it('should clear all cached arrays and delete cache entries', () => {
      // Setup cache with some data
      pool.cache = {
        'id1': [1, 2, 3],
        'id2': ['a', 'b', 'c'],
        'id3': [{}, {}]
      };

      // Verify initial state
      expect(pool.cache.id1).toEqual([1, 2, 3]);
      expect(pool.cache.id2).toEqual(['a', 'b', 'c']);
      expect(pool.cache.id3).toEqual([{}, {}]);

      // Execute destroy
      pool.destroy();

      // Verify cache is empty
      expect(pool.cache).toEqual({});
      expect(Object.keys(pool.cache)).toHaveLength(0);
    });

    it('should handle empty cache gracefully', () => {
      pool.cache = {};

      // Should not throw any errors
      expect(() => pool.destroy()).not.toThrow();

      // Cache should remain empty
      expect(pool.cache).toEqual({});
    });

    it('should set array length to 0 before deletion', () => {
      const mockArray = [1, 2, 3, 4, 5];
      const originalLength = mockArray.length;

      pool.cache = {
        'testId': mockArray
      };

      pool.destroy();

      // The array should have been modified to length 0 before deletion
      expect(mockArray.length).toBe(0);
      expect(pool.cache).not.toHaveProperty('testId');
    });

    it('should work with cache containing multiple entries', () => {
      const arrays = [
        [1, 2],
        [3, 4, 5],
        ['x', 'y', 'z']
      ];

      pool.cache = {
        'a': arrays[0],
        'b': arrays[1],
        'c': arrays[2]
      };

      pool.destroy();

      // All arrays should have length 0
      arrays.forEach(arr => {
        expect(arr.length).toBe(0);
      });

      // Cache should be empty
      expect(pool.cache).toEqual({});
    });

    it('should not affect the total property', () => {
      pool.total = 10;
      pool.cache = {
        'id1': [1, 2, 3]
      };

      pool.destroy();

      // total should remain unchanged
      expect(pool.total).toBe(10);
      // cache should be empty
      expect(pool.cache).toEqual({});
    });
  });
});

